fn append_loop_helper(items:&mut Vec<crate::translation::surface::SItem>,path:&[String],function:crate::translation::surface::SFn)->Result<()>{if path.is_empty(){items.push(crate::translation::surface::SItem::Fn(function));return Ok(());}let nested=items.iter_mut().find_map(|item|if let crate::translation::surface::SItem::Module(module)=item{(module.name==path[0]).then_some(&mut module.items)}else{None}).ok_or_else(||fail("the finite loop helper needs its actual source module inventory"))?;append_loop_helper(nested,&path[1..],function)}
